  3	public final class RedBlackTree {
  4	    private enum Rotation {
  5	        NONE,
  6	        LEFT_LEFT,
  7	        RIGHT_RIGHT,
  8	        LEFT_RIGHT,
  9	        RIGHT_LEFT
 10	    }
 11	
 12	    private enum Side {
 13	        LEFT,
 14	        RIGHT;
 15	
 16	        private Side opposite() {
 17	            return this == LEFT ? RIGHT : LEFT;
 18	        }
 19	    }
 20	
 21	    private static final class Node {
 22	        private final int data;
 23	        private Node left;
 24	        private Node right;
 25	        private Node parent;
 26	        private RedBlackTreeColor color;
 27	
 28	        private Node(int data, RedBlackTreeColor color) {
 29	            this.data = data;
 30	            this.color = color;
 31	        }
 32	
 33	        private Node child(Side side) {
 34	            return side == Side.LEFT ? left : right;
 35	        }
 36	
 37	        private void setChild(Side side, Node child) {
 38	            if (side == Side.LEFT) {
 39	                left = child;
 40	            } else {
 41	                right = child;
 42	            }
 43	        }
 44	
 45	        private void attachChild(Side side, Node child) {
 46	            setChild(side, child);
 47	            if (child != null) {
 48	                child.parent = this;
 49	            }
 50	        }
 51	    }
 52	
 53	    private static final class InsertionResult {
 54	        private final Node root;
 55	        private final Rotation pendingRotation;
 56	
 57	        private InsertionResult(Node root, Rotation pendingRotation) {
 58	            this.root = root;
 59	            this.pendingRotation = pendingRotation;
 60	        }
 61	    }
 62	
 63	    private Node root;
 64	
 65	    public void insert(int data) {
 66	        if (root == null) {
 67	            root = new Node(data, RedBlackTreeColor.BLACK);
 68	            return;
 69	        }
 70	
 71	        root = insert(root, data).root;
 72	        root.color = RedBlackTreeColor.BLACK;
 73	        root.parent = null;
 74	    }
 75	
 76	    public void insertAll(int... values) {
 77	        for (int value : values) {
 78	            insert(value);
 79	        }
 80	    }
 81	
 82	    public List<Integer> inorderValues() {
 83	        return snapshot().inorderValues();
 84	    }
 85	
 86	    public String inorderString() {
 87	        return snapshot().inorderString();
 88	    }
 89	
 90	    public void inorderTraversal() {
 91	        System.out.print(inorderString());
 92	    }
 93	
 94	    public String formatTree() {
 95	        return snapshot().formatTree();
 96	    }
 97	
 98	    public void printTree() {
 99	        System.out.print(formatTree());
100	    }
101	
102	    public boolean isValidRedBlackTree() {
103	        return snapshot().isValid();
104	    }
105	
106	    private InsertionResult insert(Node current, int data) {
107	        if (current == null) {
108	            return new InsertionResult(new Node(data, RedBlackTreeColor.RED), Rotation.NONE);
109	        }
110	
111	        Side insertionSide = insertionSide(current, data);
112	        InsertionResult childResult = insert(current.child(insertionSide), data);
113	        current.attachChild(insertionSide, childResult.root);
114	        boolean redRedConflict = hasRedRedConflict(current, insertionSide);
115	
116	        current = applyPendingRotation(current, childResult.pendingRotation);
117	        Rotation pendingRotation = Rotation.NONE;
118	
119	        if (redRedConflict) {
120	            pendingRotation = resolveRedRedConflict(current);
121	        }
122	
123	        return new InsertionResult(current, pendingRotation);
124	    }
125	
126	    private Node applyPendingRotation(Node current, Rotation pendingRotation) {
127	        switch (pendingRotation) {
128	            case LEFT_LEFT:
129	                current = rotate(current, Side.RIGHT);
130	                recolorAfterSingleRotation(current, Side.LEFT);
131	                break;
132	            case RIGHT_RIGHT:
133	                current = rotate(current, Side.LEFT);
134	                recolorAfterSingleRotation(current, Side.RIGHT);
135	                break;
136	            case RIGHT_LEFT:
137	                rotateChild(current, Side.RIGHT, Side.LEFT);
138	                current = rotate(current, Side.RIGHT);
139	                recolorAfterSingleRotation(current, Side.LEFT);
140	                break;
141	            case LEFT_RIGHT:
142	                rotateChild(current, Side.LEFT, Side.RIGHT);
143	                current = rotate(current, Side.LEFT);
144	                recolorAfterSingleRotation(current, Side.RIGHT);
145	                break;
146	            case NONE:
147	                break;
148	        }
149	
150	        return current;
151	    }
152	
153	    private Rotation resolveRedRedConflict(Node current) {
154	        Node parent = current.parent;
155	        Side side = sideOf(parent, current);
156	        Node uncle = siblingChild(parent, side);
157	
158	        if (isBlack(uncle)) {
159	            return chooseRotation(current, side);
160	        }
161	
162	        recolorForRedUncle(current, uncle);
163	        return Rotation.NONE;
164	    }
165	
166	    private void recolorAfterSingleRotation(Node newRoot, Side childSide) {
167	        newRoot.color = RedBlackTreeColor.BLACK;
168	        newRoot.child(childSide).color = RedBlackTreeColor.RED;
169	    }
170	
171	    private void recolorForRedUncle(Node current, Node uncle) {
172	        uncle.color = RedBlackTreeColor.BLACK;
173	        current.color = RedBlackTreeColor.BLACK;
174	        if (current.parent != root) {
175	            current.parent.color = RedBlackTreeColor.RED;
176	        }
177	    }
178	
179	    private Rotation chooseRotation(Node current, Side side) {
180	        if (side == Side.RIGHT) {
181	            if (isRed(current.child(Side.LEFT))) {
182	                return Rotation.RIGHT_LEFT;
183	            }
184	            if (isRed(current.child(Side.RIGHT))) {
185	                return Rotation.LEFT_LEFT;
186	            }
187	        } else {
188	            if (isRed(current.child(Side.LEFT))) {
189	                return Rotation.RIGHT_RIGHT;
190	            }
191	            if (isRed(current.child(Side.RIGHT))) {
192	                return Rotation.LEFT_RIGHT;
193	            }
194	        }
195	
196	        return Rotation.NONE;
197	    }
198	
199	    private Node rotate(Node node, Side pivotSide) {
200	        Node originalParent = node.parent;
201	        Node pivot = node.child(pivotSide);
202	        Side transferredSide = pivotSide.opposite();
203	        Node transferredSubtree = pivot.child(transferredSide);
204	
205	        node.attachChild(pivotSide, transferredSubtree);
206	        pivot.attachChild(transferredSide, node);
207	        pivot.parent = originalParent;
208	
209	        return pivot;
210	    }
211	
212	    private boolean isRed(Node node) {
213	        return node != null && node.color == RedBlackTreeColor.RED;
214	    }
215	
216	    private boolean isBlack(Node node) {
217	        return node == null || node.color == RedBlackTreeColor.BLACK;
218	    }
219	
220	    private Side insertionSide(Node current, int data) {
221	        return data < current.data ? Side.LEFT : Side.RIGHT;
222	    }
223	
224	    private boolean hasRedRedConflict(Node current, Side childSide) {
225	        return current != root && isRed(current) && isRed(current.child(childSide));
226	    }
227	
228	    private Side sideOf(Node parent, Node child) {
229	        return parent.right == child ? Side.RIGHT : Side.LEFT;
230	    }
231	
232	    private Node siblingChild(Node parent, Side side) {
233	        return side == Side.RIGHT ? parent.left : parent.right;
234	    }
235	
236	    private void rotateChild(Node current, Side childSide, Side pivotSide) {
237	        current.attachChild(childSide, rotate(current.child(childSide), pivotSide));
238	    }
239	
240	    RedBlackTreeSnapshot snapshot() {
241	        return new RedBlackTreeSnapshot(copyOf(root));
242	    }
243	
244	    private RedBlackTreeSnapshot.NodeSnapshot copyOf(Node node) {
245	        if (node == null) {
246	            return null;
247	        }
248	
249	        return new RedBlackTreeSnapshot.NodeSnapshot(
250	            node.data,
251	            node.color,
252	            copyOf(node.left),
253	            copyOf(node.right)
254	        );
255	    }
256	}

